rows = [line.split('|') for line in data.strip().splitlines() if line.strip()]
assert all(len(row) == 4 for row in rows)
q = lambda s: json.dumps(s, ensure_ascii=False)
lines = ['// Generated from build-blood-hunter-text.py; user-provided pre-2024 PDF.', 'namespace Taruck.CharacterCreation {', 'public static class CharacterBloodHunterText {', 'internal static string Get(string key) { switch(key) {']
lines += ['case '+q(key)+': return '+q(ua)+';' for key,ua,en,ru in rows]
lines += ['default: throw new System.ArgumentException("Unknown Blood Hunter text: " + key);', '} }', 'public static readonly string[] Templates = new string[] {' + ','.join(q(ua) for _,ua,_,_ in rows if '{0}' in ua) + '};', '} }']
(root/'Assets/Skripts/Domain/CharacterBloodHunterText.cs').write_text('\n'.join(lines)+'\n',encoding='utf-8')
path = root/'Assets/Resources/Localization.txt'
old=path.read_text(encoding='utf-8-sig'); known={l.split('\t')[0] for l in old.splitlines()}
new=[]
for _,ua,en,ru in rows:
    for values in [(ua,en,ru),tuple(s.split(':')[0] for s in (ua,en,ru))]:
        if values[0] not in known:
            new.append('\t'.join(values)); known.add(values[0])
path.write_text(old.rstrip('\n')+'\n'+'\n'.join(new)+'\n',encoding='utf-8')
print('Blood Hunter texts:',len(rows),'new translations:',len(new))
